body.content:
{%- comment -%}force-sync{%- endcomment -%}
<!doctype html>
<html class="js" lang="{{ request.locale.iso_code }}">
<head>
<link rel="stylesheet" href="{{ 'component-list-social.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-list-payment.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-rating.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'section-footer.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'mask-blobs.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-newsletter.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'quantity-popover.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-list-menu.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'quick-order-list.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'template-collection.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-volume-pricing.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-price.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-slider.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-card.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'section-collection-list.css' | asset_url }}" media="print" onload="this.media='all'">
<link rel="stylesheet" href="{{ 'component-slideshow.css' | asset_url }}" media="print" onload="this.media='all'">
  <meta charset="utf-8">
  <meta http-equiv="X-UA-Compatible" content="IE=edge">
  <meta name="theme-color" content="">
  {%- liquid
    assign resolved_canonical_url = canonical_url | default: request.url | default: request.origin
    if request.page_type == 'product' and resolved_canonical_url contains '?'
      assign resolved_canonical_url = resolved_canonical_url | split: '?' | first
    endif

    assign parameterized_product_noindex = false
    if request.page_type == 'product'
      assign request_query_string = request.query_string | default: ''
      if request_query_string != blank
        assign parameterized_product_noindex = true
      endif
    endif
  -%}
  {% comment %}theme-check-disable RemoteAsset{% endcomment %}
  <link rel="canonical" href="{{ resolved_canonical_url | escape }}">
  {% comment %}theme-check-enable RemoteAsset{% endcomment %}
 <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=5.0, user-scalable=yes">

  {% if template == 'product' %}
  {%- assign taxonomy_category1 = product.metafields.custom.category1 | default: '' | strip -%}
  {%- assign taxonomy_subcategory = product.metafields.custom.subcategory | default: '' | strip -%}
  {%- assign taxonomy_type = product.metafields.custom.type | default: product.type | default: '' | strip -%}
  {%- assign taxonomy_style = product.metafields.custom.style | default: '' | strip -%}
  {%- assign taxonomy_pattern = product.metafields.custom.pattern | default: '' | strip -%}
  {%- for tag in product.tags -%}
    {%- assign normalized_tag = tag | strip -%}
    {%- assign normalized_tag_downcase = normalized_tag | downcase -%}
    {%- if taxonomy_category1 == blank and normalized_tag_downcase contains 'category1:' -%}
      {%- assign taxonomy_category1 = normalized_tag | split: ':' | last | strip -%}
    {%- elsif taxonomy_category1 == blank and normalized_tag_downcase contains 'category:' -%}
      {%- assign taxonomy_category1 = normalized_tag | split: ':' | last | strip -%}
    {%- endif -%}
    {%- if taxonomy_subcategory == blank and normalized_tag_downcase contains 'subcategory:' -%}
      {%- assign taxonomy_subcategory = normalized_tag | split: ':' | last | strip -%}
    {%- endif -%}
    {%- if taxonomy_type == blank and normalized_tag_downcase contains 'type:' -%}
      {%- assign taxonomy_type = normalized_tag | split: ':' | last | strip -%}
    {%- endif -%}
    {%- if taxonomy_style == blank and normalized_tag_downcase contains 'style:' -%}
      {%- assign taxonomy_style = normalized_tag | split: ':' | last | strip -%}
    {%- endif -%}
    {%- if taxonomy_pattern == blank and normalized_tag_downcase contains 'pattern:' -%}
      {%- assign taxonomy_pattern = normalized_tag | split: ':' | last | strip -%}
    {%- endif -%}
  {%- endfor -%}
  {%- if taxonomy_category1 != blank -%}
  <meta name="custom-category1" content="{{ taxonomy_category1 | escape }}">
  {%- endif -%}
  {%- if taxonomy_subcategory != blank -%}
  <meta name="custom-subcategory" content="{{ taxonomy_subcategory | escape }}">
  {%- endif -%}
  {%- if taxonomy_type != blank -%}
  <meta name="custom-type" content="{{ taxonomy_type | escape }}">
  {%- endif -%}
  {%- if taxonomy_style != blank -%}
  <meta name="custom-style" content="{{ taxonomy_style | escape }}">
  {%- endif -%}
  {%- if taxonomy_pattern != blank -%}
  <meta name="custom-pattern" content="{{ taxonomy_pattern | escape }}">
  {%- endif -%}
  {%- assign product_lcp_media = product.featured_media -%}
  {%- if product_lcp_media == blank -%}
    {%- assign product_lcp_media = product.selected_or_first_available_variant.featured_media -%}
  {%- endif -%}
  {%- if product_lcp_media != blank and product_lcp_media.preview_image != blank -%}
    {%- assign product_lcp_image = product_lcp_media.preview_image -%}
    {% comment %}theme-check-disable AssetPreload{% endcomment %}
    <link
      rel="preload"
      as="image"
      href="{{ product_lcp_image | image_url: width: 823 }}"
      imagesrcset="
        {%- if product_lcp_image.width >= 493 -%}{{ product_lcp_image | image_url: width: 493 }} 493w,{%- endif -%}
        {%- if product_lcp_image.width >= 600 -%}{{ product_lcp_image | image_url: width: 600 }} 600w,{%- endif -%}
        {%- if product_lcp_image.width >= 713 -%}{{ product_lcp_image | image_url: width: 713 }} 713w,{%- endif -%}
        {%- if product_lcp_image.width >= 823 -%}{{ product_lcp_image | image_url: width: 823 }} 823w,{%- endif -%}
        {%- if product_lcp_image.width >= 990 -%}{{ product_lcp_image | image_url: width: 990 }} 990w,{%- endif -%}
        {%- if product_lcp_image.width >= 1100 -%}{{ product_lcp_image | image_url: width: 1100 }} 1100w,{%- endif -%}
        {{ product_lcp_image | image_url }} {{ product_lcp_image.width }}w
      "
      imagesizes="(min-width: 990px) 50vw, 100vw"
    >
    {% comment %}theme-check-enable AssetPreload{% endcomment %}
  {%- endif -%}
  {% endif %}

  {%- liquid
    assign resolved_page_title = page_title
    assign resolved_page_description = page_description
    assign collection_seo_display_title = blank
    assign collection_seo_meta_title = blank
    assign collection_seo_meta_description = blank
    assign collection_seo_force_theme = blank
    assign product_seo_description = blank
    assign append_shop_name_to_title = true

    if request.page_type == 'collection' and collection != blank
      capture collection_seo_display_title
        render 'collection-seo-fallback', collection: collection, field: 'display_title'
      endcapture
      assign collection_seo_display_title = collection_seo_display_title | strip

      capture collection_seo_meta_title
        render 'collection-seo-fallback', collection: collection, field: 'meta_title'
      endcapture
      assign collection_seo_meta_title = collection_seo_meta_title | strip

      capture collection_seo_meta_description
        render 'collection-seo-fallback', collection: collection, field: 'meta_description'
      endcapture
      assign collection_seo_meta_description = collection_seo_meta_description | strip

      capture collection_seo_force_theme
        render 'collection-seo-fallback', collection: collection, field: 'force_theme_seo'
      endcapture
      assign collection_seo_force_theme = collection_seo_force_theme | strip
    elsif request.page_type == 'product' and product != blank
      capture product_seo_description
        render 'product-seo-description-fallback', product: product, collection: collection, page_description: resolved_page_description
      endcapture
      assign product_seo_description = product_seo_description | strip
      assign product_title_locale_root = request.locale.iso_code | default: localization.language.iso_code | default: '' | split: '-' | first | downcase
      if product.handle == 'golden-daisy-mommy-and-me-set' and product_title_locale_root == 'en'
        assign resolved_page_title = 'Golden Daisy Mommy & Me Matching Separates'
      endif
    endif

    if request.page_type == 'index'
      assign resolved_page_title = 'Mommy and Me Dresses | Family Matching Outfits'
      assign resolved_page_description = 'Shop mommy and me dresses, mother daughter matching outfits, and family matching clothes for photos, vacations, and everyday moments.'
      assign append_shop_name_to_title = false
    elsif request.page_type == 'blog' and blog != blank and blog.handle == 'news'
      assign resolved_page_title = 'Style Journal'
    endif

    if request.page_type == 'collection' and collection != blank
      if collection_seo_force_theme == 'true'
        assign append_shop_name_to_title = false
        if collection_seo_meta_title != blank
          assign resolved_page_title = collection_seo_meta_title
        elsif collection_seo_display_title != blank
          assign resolved_page_title = collection_seo_display_title
        endif
      elsif collection.handle == 'all' or collection.handle == 'swimsuits' or resolved_page_title == blank or resolved_page_title == collection.title
        if collection_seo_meta_title != blank
          assign resolved_page_title = collection_seo_meta_title
        elsif collection_seo_display_title != blank
          assign resolved_page_title = collection_seo_display_title
        endif
      endif
    endif

    if request.page_type == 'collection' and collection != blank and collection_seo_force_theme == 'true' and collection_seo_meta_description != blank
      assign resolved_page_description = collection_seo_meta_description
    elsif request.page_type == 'product' and product != blank and product_seo_description != blank
      assign resolved_page_description = product_seo_description
    elsif resolved_page_description == blank
      if request.page_type == 'collection' and collection != blank and collection_seo_meta_description != blank
        assign resolved_page_description = collection_seo_meta_description
      elsif request.page_type == 'blog' and blog != blank and blog.handle == 'news'
        assign resolved_page_description = 'Outfit guides, styling tips, and shopping advice for mommy and me, daddy and me, and family matching looks.'
      elsif request.page_type == 'article' and article != blank
        assign resolved_page_description = article.excerpt | default: article.content | strip_html | truncatewords: 28
      endif
    endif

    if resolved_page_description != blank
      assign resolved_page_description = resolved_page_description | replace: 'Free shipping + returns', 'Standard shipping included + easy returns'
      assign resolved_page_description = resolved_page_description | replace: 'Free Shipping + Returns', 'Standard Shipping Included + Easy Returns'
      assign resolved_page_description = resolved_page_description | replace: 'FREE SHIPPING + RETURNS', 'STANDARD SHIPPING INCLUDED + EASY RETURNS'
      assign resolved_page_description = resolved_page_description | replace: 'Free shipping on all orders', 'Standard shipping included'
      assign resolved_page_description = resolved_page_description | replace: 'FREE SHIPPING ON ALL ORDERS', 'STANDARD SHIPPING INCLUDED'
      assign resolved_page_description = resolved_page_description | replace: 'Free shipping', 'Standard shipping included'
      assign resolved_page_description = resolved_page_description | replace: 'Free Shipping', 'Standard Shipping Included'
      assign resolved_page_description = resolved_page_description | replace: 'FREE SHIPPING', 'STANDARD SHIPPING INCLUDED'
      assign resolved_page_description = resolved_page_description | replace: 'Standard shipping included + returns', 'Standard shipping included + easy returns'
      assign resolved_page_description = resolved_page_description | replace: 'Standard Shipping Included + Returns', 'Standard Shipping Included + Easy Returns'
      assign resolved_page_description = resolved_page_description | replace: 'STANDARD SHIPPING INCLUDED + RETURNS', 'STANDARD SHIPPING INCLUDED + EASY RETURNS'
      assign resolved_page_description = resolved_page_description | replace: '+ returns', '+ easy returns'
      assign resolved_page_description = resolved_page_description | replace: '+ Returns', '+ Easy Returns'
      assign resolved_page_description = resolved_page_description | replace: '+ RETURNS', '+ EASY RETURNS'
      assign resolved_page_description = resolved_page_description | replace: '30-day easy returns', 'easy returns'
      assign resolved_page_description = resolved_page_description | replace: '30-Day Easy Returns', 'Easy Returns'
      assign resolved_page_description = resolved_page_description | replace: '30-DAY EASY RETURNS', 'EASY RETURNS'
      if resolved_page_description contains 'Standard shipping included' and resolved_page_description contains 'returns'
        assign resolved_page_description_prefix = resolved_page_description | split: 'Standard shipping included' | first
        assign resolved_page_description = resolved_page_description_prefix | append: 'Standard shipping included + easy returns.'
      elsif resolved_page_description contains 'Standard Shipping Included' and resolved_page_description contains 'Returns'
        assign resolved_page_description_prefix = resolved_page_description | split: 'Standard Shipping Included' | first
        assign resolved_page_description = resolved_page_description_prefix | append: 'Standard Shipping Included + Easy Returns.'
      elsif resolved_page_description contains 'STANDARD SHIPPING INCLUDED' and resolved_page_description contains 'RETURNS'
        assign resolved_page_description_prefix = resolved_page_description | split: 'STANDARD SHIPPING INCLUDED' | first
        assign resolved_page_description = resolved_page_description_prefix | append: 'STANDARD SHIPPING INCLUDED + EASY RETURNS.'
      endif
    endif
  -%}

  <!-- Title and Meta Description for SEO -->
  <title>
    {{ resolved_page_title }}
    {%- if current_tags %} &ndash; tagged "{{ current_tags | join: ', ' }}"{% endif -%}
    {%- if current_page != 1 %} &ndash; Page {{ current_page }}{% endif -%}
    {%- if append_shop_name_to_title -%}
      {%- unless resolved_page_title contains shop.name -%} &ndash; {{ shop.name }}{%- endunless -%}
    {%- endif -%}
  </title>
  {% if resolved_page_description %}
  <meta name="description" content="{{ resolved_page_description | replace: '30-day ', '' | replace: '30-Day ', '' | replace: '30-DAY ', '' | escape }}">
  {% endif %}

  <!-- Other Meta Tags -->
  <meta name="theme-color" content="{{ settings.color_theme }}">
  <meta name="author" content="{{ shop.name | escape }}">

 <!-- Critical CSS -->
<link rel="stylesheet" href="{{ 'theme-inline-head-static-01.css' | asset_url }}">

<link rel="stylesheet" href="{{ 'theme-inline-head-static-02.css' | asset_url }}">

<!-- CSS Stylesheets -->
{{ 'base.css' | asset_url | stylesheet_tag }}
{{ 'component-shipping-countries-v2.css' | asset_url | stylesheet_tag }}
{%- if request.page_type contains 'customers' or template.directory == 'customers' -%}
  {{ 'customer.css' | asset_url | stylesheet_tag }}
{%- endif -%}

<!-- Remove Critical CSS Files -->
<!--
{{ 'component-rating.css' | asset_url | stylesheet_tag }}
{{ 'component-list-payment.css' | asset_url | stylesheet_tag }}
{{ 'component-volume-pricing.css' | asset_url | stylesheet_tag }}
{{ 'component-newsletter.css' | asset_url | stylesheet_tag }}
{{ 'component-list-social.css' | asset_url | stylesheet_tag }}
{{ 'section-footer.css' | asset_url | stylesheet_tag }}
{{ 'component-list-menu.css' | asset_url | stylesheet_tag }}
{{ 'mask-blobs.css' | asset_url | stylesheet_tag }}
{{ 'quick-order-list.css' | asset_url | stylesheet_tag }}
{{ 'quantity-popover.css' | asset_url | stylesheet_tag }}
{{ 'template-collection.css' | asset_url | stylesheet_tag }}
{{ 'component-price.css' | asset_url | stylesheet_tag }}
{{ 'component-slider.css' | asset_url | stylesheet_tag }}
{{ 'component-slideshow.css' | asset_url | stylesheet_tag }}
{{ 'section-collection-list.css' | asset_url | stylesheet_tag }}
{{ 'component-card.css' | asset_url | stylesheet_tag }}
-->







  {%- liquid
    assign resolved_favicon_url = blank
    if settings.favicon != blank
      assign resolved_favicon_url = settings.favicon | image_url: width: 32, height: 32
    elsif settings.logo != blank
      assign resolved_favicon_url = settings.logo | image_url: width: 32, height: 32, crop: 'center'
    endif
  -%}
  {%- if resolved_favicon_url != blank -%}
    {% comment %}theme-check-disable RemoteAsset{% endcomment %}
    <link rel="icon" type="image/png" href="{{ resolved_favicon_url }}">
    {% comment %}theme-check-enable RemoteAsset{% endcomment %}
  {%- endif -%}

  {%- unless settings.type_header_font.system? and settings.type_body_font.system? -%}
    <link rel="preconnect" href="https://fonts.shopifycdn.com" crossorigin>
  {%- endunless -%}

  {%- liquid
    assign emit_organization_schema = false
    if request.page_type == 'index' or template == 'index'
      assign emit_organization_schema = true
    endif
  -%}
  {% render 'meta-tags', canonical_href: resolved_canonical_url, parameterized_product_noindex: parameterized_product_noindex %}
  {% render 'jsonld-seo', canonical_href: resolved_canonical_url, emit_organization_schema: emit_organization_schema %}

  <script>
    window.dataLayer = window.dataLayer || [];
    window.dlmAnalyticsContext = window.dlmAnalyticsContext || {};
    window.dlmAnalyticsContext.site_language = (function (rawLocale) {
      var normalized = String(rawLocale || '').trim();
      if (!normalized) return 'en';
      return normalized.split(/[-_]/)[0].toLowerCase();
    })({{ request.locale.iso_code | json }});
    window.dataLayer.push({ site_language: window.dlmAnalyticsContext.site_language });
  </script>

  <script defer src="{{ 'constants.js' | asset_url }}"></script>
  <script defer src="{{ 'pubsub.js' | asset_url }}"></script>
  <script defer src="{{ 'global.js' | asset_url }}"></script>
  {%- if request.page_type == 'index' -%}
    <script defer src="{{ 'homepage-collection-card-images.js' | asset_url }}"></script>
  {%- endif -%}
  <script>
    (function () {
      var analyticsUrl = {{ 'analytics.js' | asset_url | json }};
      if (!analyticsUrl) return;
      var hasLoaded = false;

      function loadAnalytics() {
        if (hasLoaded) return;
        hasLoaded = true;
        var script = document.createElement('script');
        script.src = analyticsUrl;
        script.defer = true;
        script.dataset.dlmAnalytics = 'true';
        document.head.appendChild(script);
      }

      function scheduleIdleLoad() {
        if ('requestIdleCallback' in window) {
          window.requestIdleCallback(loadAnalytics, { timeout: 2500 });
        } else {
          window.setTimeout(loadAnalytics, 1800);
        }
      }

      window.addEventListener('load', scheduleIdleLoad, { once: true });
      document.addEventListener('pointerdown', loadAnalytics, { once: true, passive: true, capture: true });
      document.addEventListener('keydown', loadAnalytics, { once: true, capture: true });
    })();
  </script>
  {%- if settings.animations_reveal_on_scroll -%}
    <script defer src="{{ 'animations.js' | asset_url }}"></script>
  {%- endif -%}

  <style>
    /* Compact bottom-corner cookie banner — only shown to visitors in regions
       that legally require consent (configured in Shopify admin → Customer
       privacy). When it does appear, keep it small and unobtrusive so it
       doesn't dominate the viewport. */
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner,
    html.dlm-shopify-privacy-banner-visible .shopify-pc__banner__wrapper {
      box-sizing: border-box;
      /* Tight max-width pill at bottom-left, NOT a full-width modal */
      max-width: 420px !important;
      width: calc(100% - 2rem) !important;
      min-height: 0 !important;
      max-height: none !important;
      left: 1rem !important;
      right: auto !important;
      bottom: 1rem !important;
      top: auto !important;
      transform: none !important;
      margin: 0 !important;
      padding: 14px 16px !important;
      border-radius: 12px !important;
      box-shadow: 0 8px 28px rgba(0, 0, 0, 0.18) !important;
      font-size: 12.5px !important;
      line-height: 1.45 !important;
      z-index: 9999 !important;
    }

    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner * {
      font-size: inherit !important;
      line-height: inherit !important;
    }

    /* Slim down the heading & body text inside the banner */
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner h2,
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner [class*="heading"],
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner [class*="title"] {
      font-size: 13px !important;
      margin: 0 0 4px !important;
    }

    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner p {
      margin: 0 0 8px !important;
    }

    /* Compact action buttons */
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner button,
    html.dlm-shopify-privacy-banner-visible #shopify-pc__banner [role="button"] {
      padding: 6px 12px !important;
      font-size: 12px !important;
      min-height: 0 !important;
      border-radius: 999px !important;
    }

    @media screen and (max-width: 749px) {
      html.dlm-shopify-privacy-banner-visible #shopify-pc__banner,
      html.dlm-shopify-privacy-banner-visible .shopify-pc__banner__wrapper {
        max-width: none !important;
        width: calc(100% - 1.5rem) !important;
        left: 0.75rem !important;
        right: 0.75rem !important;
        bottom: 0.75rem !important;
        padding: 12px 14px !important;
        font-size: 12px !important;
      }
    }

    html:not(.dlm-shopify-privacy-banner-visible) #shopify-pc__banner,
    html:not(.dlm-shopify-privacy-banner-visible) .shopify-pc__banner__wrapper {
      display: none !important;
      visibility: hidden !important;
    }
  </style>
  {{ content_for_header }}
  <script>
    (function () {
      var root = document.documentElement;
      var visibilityClass = 'dlm-shopify-privacy-banner-visible';
      var bannerSelectors = [
        '#shopify-pc__banner',
        '.shopify-pc__banner__wrapper',
      ];

      function showPrivacyBanner() {
        root.classList.add(visibilityClass);
      }

      function removePrivacyBannerNodes() {
        bannerSelectors.forEach(function (selector) {
          document.querySelectorAll(selector).forEach(function (node) {
            node.remove();
          });
        });
      }

      function watchForSuppressedBanner() {
        if (!document.body) return;

        var observer = new MutationObserver(function () {
          if (root.classList.contains(visibilityClass)) return;
          removePrivacyBannerNodes();
        });

        observer.observe(document.body, { childList: true, subtree: true });
        removePrivacyBannerNodes();
      }

      function initPrivacyBannerGate() {
        if (!window.Shopify || typeof window.Shopify.loadFeatures !== 'function') {
          showPrivacyBanner();
          return;
        }

        window.Shopify.loadFeatures([{ name: 'consent-tracking-api', version: '0.1' }], function (error) {
          if (error || !window.Shopify || !window.Shopify.customerPrivacy) {
            showPrivacyBanner();
            return;
          }

          var customerPrivacy = window.Shopify.customerPrivacy;
          var shouldShowConsentBanner = false;
          var isSaleOfDataRegion = false;

          try {
            shouldShowConsentBanner =
              typeof customerPrivacy.shouldShowBanner === 'function' &&
              customerPrivacy.shouldShowBanner();
          } catch (_error) {
            shouldShowConsentBanner = false;
          }

          try {
            isSaleOfDataRegion =
              typeof customerPrivacy.saleOfDataRegion === 'function' &&
              customerPrivacy.saleOfDataRegion();
          } catch (_error) {
            isSaleOfDataRegion = false;
          }

          if (shouldShowConsentBanner || isSaleOfDataRegion) {
            showPrivacyBanner();
            return;
          }

          watchForSuppressedBanner();
        });
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initPrivacyBannerGate, { once: true });
      } else {
        initPrivacyBannerGate();
      }
    })();
  </script>

  {%- liquid
    assign body_font_bold = settings.type_body_font | font_modify: 'weight', 'bold'
    assign body_font_italic = settings.type_body_font | font_modify: 'style', 'italic'
    assign body_font_bold_italic = body_font_bold | font_modify: 'style', 'italic'
    assign scheme_classes = ''
  %}

  <style>
    {{ settings.type_body_font | font_face: font_display: 'swap' }}
    {{ body_font_bold | font_face: font_display: 'swap' }}
    {{ body_font_italic | font_face: font_display: 'swap' }}
    {{ body_font_bold_italic | font_face: font_display: 'swap' }}
    {{ settings.type_header_font | font_face: font_display: 'swap' }}

    {% for scheme in settings.color_schemes -%}
      {% assign scheme_classes = scheme_classes | append: ', .color-' | append: scheme.id %}
